return [
    '68096a929a23b19971c4bf11' => ['title' => 'COLOR BOX', 'description' => 'Jeu de plateforme 3D créé avec Unreal Engine : un robot spatial change de couleur pour résoudre des énigmes et ouvrir des portes dans un univers de science-fiction.', 'longDescription' => "Color Box est un projet pédagogique de plateforme 3D. Le joueur dirige un robot spatial capable de changer de couleur pour ouvrir des portes, activer des mécanismes et résoudre des énigmes environnementales.\n\nLe développement associe C++ et les Blueprints d’Unreal Engine, pour conjuguer logique performante et itérations de conception.\n\nTrois comportements d’intelligence artificielle rythment les niveaux : un personnage guide, un ennemi à distance qui lance des orbes modifiant la couleur du joueur et un ennemi de mêlée qui le poursuit. Ils ajoutent exploration, action et tension aux énigmes. Ce projet rassemble conception de jeu, programmation C++, scripts visuels et comportements d’IA."],
    '68096d929a23b19971c4bf21' => ['title' => 'Paladin', 'description' => 'Mon premier jeu d’action à la troisième personne sous Unreal Engine, réalisé dans le cadre d’un cours : combats, esquives, parade, ennemis, boss et interface complète.', 'longDescription' => "Paladin est un jeu d’action-aventure pédagogique réalisé dans le cadre d’un cours en ligne. Ce premier projet complet sous Unreal Engine m’a permis d’explorer la conception des niveaux et des combats.\n\nLe personnage dispose de quatre attaques de mêlée, d’une esquive, d’une parade et d’un système de santé, avec animations et effets visuels. Une IA ennemie gère les déplacements et les attaques, et un combat de boss propose un défi supplémentaire.\n\nL’interface comprend un menu principal, un écran de mort et des indicateurs de santé. Les niveaux introduisent progressivement les mécaniques. Le projet constitue une première expérience complète de C++, Blueprints, conception de jeu et présentation visuelle."],
    '680980e09f2706367677b36f' => ['title' => 'Nexus', 'description' => 'Site de NexusCo, agence numérique basée à Rouen, présentant ses sites web sur mesure, applications mobiles et solutions techniques pour les entreprises.', 'longDescription' => 'NexusCo est une agence numérique basée à Rouen, en France. Son site nexusco.fr présente ses solutions sur mesure, des sites professionnels aux applications mobiles, conçues pour améliorer la visibilité, les échanges avec les utilisateurs et l’efficacité des entreprises.'],
    '680b809422684d6353d802b6' => ['title' => 'BOAST', 'description' => 'Application de marketplace Flutter en cours de développement, réunissant petites et grandes marques avec une architecture BLoC centrée sur la performance et l’évolutivité.', 'longDescription' => "Boast est une application mobile de marketplace développée avec Flutter et l’architecture BLoC. Elle vise à offrir aux petites entreprises et aux marques établies une plateforme commune pour présenter et vendre leurs produits.\n\nLe projet est en cours de construction. Les fonctionnalités prévues comprennent des catalogues, profils de marques, listes de souhaits, un paiement sécurisé et des recommandations personnalisées.\n\nLe choix de BLoC facilite la gestion d’état, les interfaces réactives et la maintenance. L’objectif est une expérience multiplateforme soignée qui donne aussi de la visibilité aux petites marques."],
    '69b70312d6797c93fe6096f0' => ['title' => 'Reconnaissance alimentaire', 'description' => 'Comparaison de SVM, Random Forest, CNN et ResNet-50 sur Food2k : 2 000 catégories et environ un million d’images, avec une application Streamlit interactive.', 'longDescription' => "Ce projet compare quatre approches de classification d’images alimentaires sur Food2k, qui comprend 2 000 catégories et environ un million d’images.\n\nLes méthodes classiques SVM et Random Forest utilisent des caractéristiques extraites par ResNet-50 ou construites avec HOG, histogrammes de couleur, LBP et filtres de Gabor. Les approches de deep learning comprennent un CNN de cinq blocs d’environ quatre millions de paramètres et un ResNet-50 ajusté en deux étapes par transfert d’apprentissage.\n\nL’entraînement utilise une perte pondérée, la précision mixte sur GPU et une mise en cache des caractéristiques. L’évaluation mesure la précision Top-1/Top-5, le score F1 et le temps d’inférence. Le SVM avec caractéristiques CNN a atteint 90,47 % de précision Top-1 ; le CNN personnalisé a atteint 96,73 % sur un sous-ensemble de 20 classes.\n\nL’application Streamlit permet d’envoyer une image, comparer les prédictions et niveaux de confiance des modèles et visualiser leurs activations via les hooks PyTorch."],
    '69b70da752143f3fe834384b' => ['title' => 'WaiRdrobe (concept)', 'description' => 'Page de présentation d’un concept de découverte de mode assistée par IA, avec animations au défilement, graphismes 3D interactifs et esthétique brutaliste.', 'longDescription' => 'WaiRdrobe présente un concept de recommandations de tenues personnalisées auprès de boutiques locales. Cette application monopage comprend un écran de chargement, des textes animés au défilement, une forme 3D avec shaders GLSL, des tracés SVG animés, une explication en étapes, une section tarifaire et des éléments de confiance. Lenis gère le défilement et GSAP ScrollTrigger les animations. L’identité visuelle associe une esthétique brutaliste et neutre aux polices Inter et JetBrains Mono.'],
    '69b70e9952143f3fe8343852' => ['title' => 'Enerolytics — Gestion énergétique & optimisation CVC', 'description' => 'Plateforme de gestion énergétique pour les entreprises : suivi CVC en temps réel, optimisation thermodynamique et maintenance automatisée.', 'longDescription' => 'Enerolytics est une plateforme SaaS B2B full stack destinée aux gestionnaires d’énergie et de bâtiments. Elle propose des tableaux de bord Hyper-Vision en temps réel, des ordres de travail fondés sur les données et des algorithmes d’optimisation thermodynamique. L’interface existe en anglais, français, espagnol et italien et associe Recharts, GSAP, Radix UI et des formulaires EmailJS avec reCAPTCHA. Conçue pour mobile et ordinateur, elle vise plus de 30 secteurs, dont la santé, le commerce, l’hôtellerie et les centres de données. La présentation du produit met en avant jusqu’à 40 % de réduction de coûts, un suivi permanent et 99,9 % de disponibilité CVC.'],
    '69b7110952143f3fe8343867' => ['title' => 'Site Sandra AI', 'description' => 'Site institutionnel bilingue français-anglais et CMS pour Sandra AI, plateforme SaaS parisienne de communication assistée par IA pour les concessions automobiles.', 'longDescription' => "Conception et développement d’un site full stack et d’un CMS sur mesure pour Sandra AI. Des pages administrables présentent trois produits : gestion des appels par IA, SMS/WhatsApp conversationnels et chatbot.\n\nLe site comprend une présentation de l’entreprise, un blog catégorisé, un espace carrières, des témoignages avec vidéos et une page de contact. L’administration gère les rôles, le contenu bilingue, l’édition TipTap, les envois FilePond avec miniatures et une médiathèque. L’ensemble est adaptatif et animé avec GSAP et Lenis."],
    '69b7116e52143f3fe8343872' => ['title' => 'Code SARL', 'description' => 'Site de Code SARL développé en interne avec mes collègues : équipe, services et réalisations, enrichis de composants interactifs et de visuels Three.js.', 'longDescription' => "Le site Code SARL a été réalisé au sein de l’équipe de développement de l’entreprise, avec mes collègues. Il s’agit d’une collaboration interne, et non d’une mission indépendante.\n\nLe site présente l’équipe, les services de développement web et mobile, les outils numériques sur mesure et une sélection de réalisations clients. Des composants Three.js ajoutent des expériences 3D interactives au parcours, illustrant notre travail collectif en développement frontend et création technique."],
    '69b7122d52143f3fe8343884' => ['title' => 'ANDA Construction', 'description' => 'Conception et développement en freelance du site d’ANDA Construction, pour présenter ses services, ses valeurs et ses réalisations dans une interface moderne.', 'longDescription' => "J’ai conçu et développé de bout en bout le site d’ANDA Construction, entreprise française du bâtiment, dans le cadre d’une mission indépendante.\n\nLe site présente les activités résidentielles, commerciales et de rénovation, une galerie de réalisations et un espace de contact. La conception privilégie la lisibilité, l’accessibilité, les performances et l’adaptation aux mobiles, avec une identité cohérente avec le secteur et la marque du client."],
    '69b713be52143f3fe8343896' => ['title' => 'Cyber Torque', 'description' => 'Application full stack de gestion de garage : interventions, facturation, stocks, techniciens et statistiques. Projet en cours ; toutes les données de démonstration sont fictives.', 'longDescription' => "Cyber Torque est un tableau de bord de gestion de garage couvrant le parcours de réparation, de l’accueil du client et l’inspection du véhicule à l’affectation des techniciens, la facturation et le suivi des paiements.\n\nIl comprend les stocks et alertes, un éditeur visuel de documents PDF, les achats et fournisseurs, le suivi de flottes, les sessions de travail et heures supplémentaires, des rapports financiers et opérationnels et des permissions détaillées avec journal d’audit.\n\nLe développement se poursuit. Toutes les données visibles dans la démonstration sont fictives."],
